add_filter( 'woocommerce_cart_item_name', 'perfectpixel_checkout_review_image', 10, 3 );

function perfectpixel_checkout_review_image( $name, $cart_item, $cart_item_key ) {
	if ( ! is_checkout() || empty( $cart_item['data'] ) ) {
		return $name;
	}
	$size  = array( 50, 50 );
	$image = $cart_item['data']->get_image( $size, array( 'style' => 'float:left;margin:0 .75em .5em 0;border-radius:4px' ) );
	return $image . $name;
}
